function Awards() {
    return (
        <>
            <div className="container">
                <div class="row">
                    <div className="col-6">
                        <img src="Media/images/largestBroker.svg" alt />
                    </div>
                    <div className="col-6"></div>
                </div>
            </div>
        </>
    );
}

export default Awards;
